def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_pressure = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 120:
                    opp_pressure += 2
                elif bid >= 80:
                    opp_pressure += 1

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 16
    medium_supply = supply <= 19

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if tight_supply:
        danger += 2
    elif medium_supply:
        danger += 1

    if highest_prev >= 130:
        danger -= 1

    if danger >= 6:
        bid = max(110.0, highest_prev + 2.5)
    elif danger >= 4:
        bid = max(78.0, avg_prev * 0.72 + 8.0)
    elif danger >= 2:
        if highest_prev >= 120:
            bid = 34.0
        else:
            bid = max(42.0, avg_prev * 0.55 + 4.0)
    else:
        if supply >= 22:
            bid = 16.0
        elif highest_prev >= 120:
            bid = 22.0
        else:
            bid = 28.0

    if budget < 40:
        bid = min(bid, budget)
    elif budget < 90:
        bid = min(bid, budget * 0.72)
    else:
        bid = min(bid, budget * 0.9)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, 95.0))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']

    eric_last_bid = None
    eric_alive = False
    for opp_id, opp_data in opponents_status.items():
        if opp_id == "Eric":
            eric_alive = opp_data['alive']
            if eric_alive:
                prev_trace = opp_data.get('previous_trace', {})
                if prev_trace and prev_trace.get('bid') is not None:
                    eric_last_bid = prev_trace['bid']
            break

    calculated_bid = 0.0

    if eric_alive:
        eric_effective_bid = eric_last_bid if eric_last_bid is not None else 121.5

        competitive_bid = eric_effective_bid + 5.0 

        competitive_bid = max(competitive_bid, DAILY_SALARY * 0.8)

        calculated_bid = min(competitive_bid, DAILY_SALARY * 0.93)

    else:
        calculated_bid = DAILY_SALARY * 0.65

    if my_hp <= 2:
        calculated_bid = DAILY_SALARY * 0.98
    elif my_hp <= 4:
        calculated_bid = max(calculated_bid, DAILY_SALARY * 0.9)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_hp >= 8:
            calculated_bid = min(calculated_bid, DAILY_SALARY * 0.85)
        else:
             calculated_bid = max(calculated_bid, DAILY_SALARY * 0.8)

    final_bid = min(my_budget, calculated_bid)

    final_bid = max(1.0, final_bid)

    return final_bid
